import{I as e,o as p,c as t,b6 as l,J as h,w as r,j as a,a as o}from"./chunks/framework.BUXTSoD9.js";const u=JSON.parse('{"title":"The Mom Test：如何透過使用者訪談驗證需求","description":"面向零基礎讀者的 The Mom Test 入門文章。學會避免禮貌性反饋，圍繞真實行為、具體事實和已有問題做使用者訪談，把“聽起來不錯”變成更可靠的需求判斷。","frontmatter":{"title":"The Mom Test：如何透過使用者訪談驗證需求","description":"面向零基礎讀者的 The Mom Test 入門文章。學會避免禮貌性反饋，圍繞真實行為、具體事實和已有問題做使用者訪談，把“聽起來不錯”變成更可靠的需求判斷。"},"headers":[],"relativePath":"zh-tw/stage-1/appendix-mom-test/index.md","filePath":"zh-tw/stage-1/appendix-mom-test/index.md"}'),d={name:"zh-tw/stage-1/appendix-mom-test/index.md"},m=Object.assign(d,{setup(c){const n="約 <strong>1.5 小時</strong>";return(b,s)=>{const i=e("ChapterIntroduction");return p(),t("div",null,[s[1]||(s[1]=l('<h1 id="the-mom-test-如何透過使用者訪談驗證需求" tabindex="-1">The Mom Test：如何透過使用者訪談驗證需求 <a class="header-anchor" href="#the-mom-test-如何透過使用者訪談驗證需求" aria-label="Permalink to “The Mom Test：如何透過使用者訪談驗證需求”">​</a></h1><p><a id="top-mom"></a></p><h2 id="本章導讀" tabindex="-1">本章導讀 <a class="header-anchor" href="#本章導讀" aria-label="Permalink to “本章導讀”">​</a></h2>',3)),h(i,{duration:n,tags:["使用者訪談","需求驗證","使用者研究","產品調研"],coreOutput:"1 組更能問出真實資訊的訪談問題",expectedOutput:"不再把使用者的禮貌性鼓勵當成驗證，而能用真實行為判斷方向"},{default:r(()=>[...s[0]||(s[0]=[a("p",null,"很多人第一次做產品調研時，以為最重要的是“找人聊聊”。於是他們去問朋友、同事，甚至家人：",-1),a("ul",null,[a("li",null,"你覺得我這個想法怎麼樣？"),a("li",null,"如果有這樣一個產品，你會不會用？"),a("li",null,"這個功能聽起來是不是還不錯？")],-1),a("p",null,"對方往往也會給出非常鼓舞人的反饋：",-1),a("ul",null,[a("li",null,"挺好的啊"),a("li",null,"聽起來很有用"),a("li",null,"我覺得你可以試試")],-1),a("p",null,"問題在於，這些回答通常並不能幫你做判斷。它們更像是禮貌、支援，或者一種不想當場掃你興的自然反應。你以為自己得到了“市場驗證”，其實只是收集了一堆很難用來決策的安慰。",-1),a("p",null,[o("The Mom Test 這套方法，就是專門用來解決這個問題的。它提醒我們："),a("strong",null,"不是使用者在故意騙你，而是你問問題的方式，天然會把對方引向好聽但沒用的回答。")],-1)])]),_:1}),s[2]||(s[2]=l(`<div class="info custom-block"><p class="custom-block-title">最小 SOP</p><p><strong>目的</strong>：看完後，你會更清楚怎麼和使用者聊天，纔不會只聽到“聽起來不錯”，而是真的問出能幫你判斷方向的資訊。</p><p><strong>行動項</strong>：把你原本想問的 5 個問題改掉，優先問“最近一次發生在什麼時候”“你當時怎麼處理”。</p><p><strong>結果</strong>：你會更容易分清哪些是意見，哪些纔是真正能支撐判斷的證據。</p><p><strong>關鍵詞跳轉</strong>：<a href="#mom-what">The Mom Test 是什麼</a> · <a href="#mom-principles">三個核心原則</a> · <a href="#mom-ai">AI 怎麼幫你</a></p></div><h2 id="你將學到以下內容" tabindex="-1">你將學到以下內容 <a class="header-anchor" href="#你將學到以下內容" aria-label="Permalink to “你將學到以下內容”">​</a></h2><ol><li>The Mom Test 到底在解決什麼問題，為什麼很多“使用者調研”其實沒有調研到真實資訊</li><li>這套方法最核心的幾個原則：少問意見，多問行為；少問假設，多問事實</li><li>怎樣把一個容易得到假陽性反饋的問題，改成更有價值的訪談問題</li><li>如何把 The Mom Test 和 JTBD、需求驗證、MVP 判斷連起來使用</li></ol><p><a id="mom-what"></a></p><h2 id="_1-the-mom-test-到底是什麼" tabindex="-1"><a href="#top-mom">1. The Mom Test 到底是什麼</a> <a class="header-anchor" href="#_1-the-mom-test-到底是什麼" aria-label="Permalink to “1. The Mom Test 到底是什麼”">​</a></h2><p>The Mom Test 來自 Rob Fitzpatrick 的同名書籍。它的名字聽起來有點像玩笑，但點得非常準：</p><p><strong>就算是你媽媽，也很難直接告訴你“這是個爛想法”。</strong></p><p>原因不是她不誠實，而是：</p><ul><li>她不想傷害你</li><li>她會下意識鼓勵你</li><li>她很容易順著你的表達方式回答</li></ul><p>其實不只是媽媽，朋友、同事、前同學，甚至很多陌生人，在面對你的產品想法時，也常常會給出類似的“正向反饋”。這不代表需求真的存在，只代表你把問題問成了一個很容易得到好聽答案的形式。</p><p>所以，The Mom Test 的重點從來不是“別問媽媽”，而是：</p><p><strong>別把問題問成任何人都會順著你回答的樣子。</strong></p><p>這套方法真正想教你的，是如何透過對話，拿到更接近真實需求的資訊，而不是收集一堆讓自己感覺良好的評論。</p><h2 id="_2-它解決的核心問題是什麼" tabindex="-1">2. 它解決的核心問題是什麼 <a class="header-anchor" href="#_2-它解決的核心問題是什麼" aria-label="Permalink to “2. 它解決的核心問題是什麼”">​</a></h2><p>The Mom Test 主要解決的是一種非常常見的認知錯覺：</p><p><strong>把禮貌性的積極反饋，當成真實需求。</strong></p><p>比如你問：</p><ul><li>你覺得這個 App 想法怎麼樣？</li><li>如果我做一個 AI 幫你寫簡歷的工具，你會用嗎？</li><li>這個功能是不是很有價值？</li></ul><p>這些問題的共同特點是：</p><ul><li>它們都在問“意見”</li><li>它們都帶著一點暗示</li><li>它們都在談一個還沒發生的未來</li></ul><p>而人對“意見”和“未來假設”的回答，通常都不穩定。很多人會高估自己的興趣、高估自己的執行力，也會高估自己未來的購買意願。</p><p>所以 The Mom Test 提醒你：</p><ul><li>不要太相信別人對你點子的評價</li><li>不要太相信別人對未來行為的預測</li><li>要儘量回到使用者已經發生過的真實行為裡</li></ul><p>因為和“你會不會用”相比，“你上次怎麼處理這件事的”往往更接近真相。</p><p><a id="mom-principles"></a></p><h2 id="_3-三個最核心的原則" tabindex="-1"><a href="#top-mom">3. 三個最核心的原則</a> <a class="header-anchor" href="#_3-三個最核心的原則" aria-label="Permalink to “3. 三個最核心的原則”">​</a></h2><p>如果你只想先記住最重要的部分，可以先記下面這三個原則。</p><h3 id="_3-1-少談你的點子-多談使用者過去的真實經歷" tabindex="-1">3.1 少談你的點子，多談使用者過去的真實經歷 <a class="header-anchor" href="#_3-1-少談你的點子-多談使用者過去的真實經歷" aria-label="Permalink to “3.1 少談你的點子，多談使用者過去的真實經歷”">​</a></h3><p>很多無效訪談一開場就講自己的方案，講自己多麼興奮，講自己準備做什麼產品。問題是，一旦你講得太多，對方就很容易切換到“配合你”“鼓勵你”的狀態。</p><p>相比之下，更好的方式是把重點放在對方的經歷上：</p><ul><li>最近一次遇到這個問題是什麼時候？</li><li>當時你在做什麼？</li><li>你最後是怎麼處理的？</li><li>哪一步最麻煩？</li></ul><p>你會發現，這類問題能更自然地把對話帶回現實，而不是停留在想象中的偏好。</p><h3 id="_3-2-少問抽象意見-多問具體事實" tabindex="-1">3.2 少問抽象意見，多問具體事實 <a class="header-anchor" href="#_3-2-少問抽象意見-多問具體事實" aria-label="Permalink to “3.2 少問抽象意見，多問具體事實”">​</a></h3><p>“我覺得這個功能挺好”“聽起來不錯”“好像有點用”，這些表達都太抽象了，很難指導產品決策。</p><p>更有價值的資訊通常長這樣：</p><ul><li>我上週剛為了這件事折騰了 2 小時</li><li>我現在是用 Excel 加微信硬撐</li><li>我上個月已經為類似工具花過錢</li><li>我最怕的是做錯，不是做慢</li></ul><p>這些纔是真正能幫你判斷問題強度、頻率和付費可能性的資訊。</p><h3 id="_3-3-少問使用者想要什麼方案-多看他現在怎麼解決問題" tabindex="-1">3.3 少問使用者想要什麼方案，多看他現在怎麼解決問題 <a class="header-anchor" href="#_3-3-少問使用者想要什麼方案-多看他現在怎麼解決問題" aria-label="Permalink to “3.3 少問使用者想要什麼方案，多看他現在怎麼解決問題”">​</a></h3><p>使用者很擅長描述自己的困擾，但不一定擅長設計解決方案。</p><p>如果你問：</p><ul><li>你想不想要一個 AI 幫你自動做這個？</li><li>你覺得加個智慧功能有沒有幫助？</li></ul><p>你得到的，通常只是對某個方案的模糊態度，而不是需求本身。</p><p>更好的問題是：</p><ul><li>你現在用什麼方法處理這個問題？</li><li>為什麼你會選擇這種方式？</li><li>它哪裡不夠好？</li></ul><p>看清現有替代方案，往往比直接問“你想要什麼”更重要。</p><h2 id="_4-為什麼人們總會給你好聽但沒用的回答" tabindex="-1">4. 為什麼人們總會給你好聽但沒用的回答 <a class="header-anchor" href="#_4-為什麼人們總會給你好聽但沒用的回答" aria-label="Permalink to “4. 為什麼人們總會給你好聽但沒用的回答”">​</a></h2><p>如果你能理解這件事，做訪談時就會少很多誤判。</p><h3 id="_4-1-人會下意識地保持禮貌" tabindex="-1">4.1 人會下意識地保持禮貌 <a class="header-anchor" href="#_4-1-人會下意識地保持禮貌" aria-label="Permalink to “4.1 人會下意識地保持禮貌”">​</a></h3><p>尤其當對話物件和你有關係時，對方很難直接說：</p><ul><li>這個方向聽起來不太行</li><li>我根本不會用</li><li>這個問題對我沒那麼重要</li></ul><p>他更可能說“挺好的”“有機會可以做做看”。</p><h3 id="_4-2-人會高估未來的自己" tabindex="-1">4.2 人會高估未來的自己 <a class="header-anchor" href="#_4-2-人會高估未來的自己" aria-label="Permalink to “4.2 人會高估未來的自己”">​</a></h3><p>很多人真心相信自己未來會：</p><ul><li>更自律</li><li>更願意學習</li><li>更願意付費</li><li>更願意嘗試新工具</li></ul><p>所以“如果有的話我應該會用”這句話，常常並不等於未來真的會用。</p><h3 id="_4-3-你的提問方式本身就在引導答案" tabindex="-1">4.3 你的提問方式本身就在引導答案 <a class="header-anchor" href="#_4-3-你的提問方式本身就在引導答案" aria-label="Permalink to “4.3 你的提問方式本身就在引導答案”">​</a></h3><p>當你問：</p><ul><li>我這個想法是不是挺好？</li><li>這個功能對你來說是不是很有幫助？</li></ul><p>你其實已經偷偷把“正確答案”塞進問題裡了。</p><p>這也是為什麼 The Mom Test 特別強調：<strong>不要把訪談做成你在尋找認可。</strong></p><h2 id="_5-直接對比-什麼問題容易問廢-什麼問題更有價值" tabindex="-1">5. 直接對比：什麼問題容易問廢，什麼問題更有價值 <a class="header-anchor" href="#_5-直接對比-什麼問題容易問廢-什麼問題更有價值" aria-label="Permalink to “5. 直接對比：什麼問題容易問廢，什麼問題更有價值”">​</a></h2><p>下面這些對照，幾乎是每個新手都會用到的。</p><table tabindex="0"><thead><tr><th>容易問廢的問題</th><th>更有價值的問題</th></tr></thead><tbody><tr><td>你覺得我這個想法怎麼樣？</td><td>你最近一次遇到這個問題是什麼時候？</td></tr><tr><td>如果有這個產品你會用嗎？</td><td>你現在是怎麼處理這件事的？</td></tr><tr><td>你願意為這個功能付費嗎？</td><td>你上次為了這個問題花過錢嗎？花在什麼上？</td></tr><tr><td>你覺得這個功能重要嗎？</td><td>這個流程裡最煩、最慢、最不放心的是哪一步？</td></tr><tr><td>你想不想要一個 AI 幫你自動做？</td><td>你現在為什麼還沒有找到更順手的解決辦法？</td></tr></tbody></table><p>這張表最重要的不是具體句子，而是背後的方向：</p><ul><li>從意見走向事實</li><li>從未來走向過去</li><li>從你的方案走向使用者的問題</li></ul><h2 id="_6-一個零基礎也能立刻用的訪談節奏" tabindex="-1">6. 一個零基礎也能立刻用的訪談節奏 <a class="header-anchor" href="#_6-一個零基礎也能立刻用的訪談節奏" aria-label="Permalink to “6. 一個零基礎也能立刻用的訪談節奏”">​</a></h2><p>如果你現在就想去找人聊，可以直接按下面這個順序來。</p><h3 id="_6-1-開場-說明你在學習-不是在推銷" tabindex="-1">6.1 開場：說明你在學習，不是在推銷 <a class="header-anchor" href="#_6-1-開場-說明你在學習-不是在推銷" aria-label="Permalink to “6.1 開場：說明你在學習，不是在推銷”">​</a></h3><p>比如：</p><blockquote><p>我最近在研究大家怎麼處理這類問題，想先了解真實情況，不是來賣東西的。</p></blockquote><p>這種表達會讓對方更容易放下“我要給你積極反饋”的心理負擔。</p><h3 id="_6-2-從最近一次真實經歷開始問" tabindex="-1">6.2 從最近一次真實經歷開始問 <a class="header-anchor" href="#_6-2-從最近一次真實經歷開始問" aria-label="Permalink to “6.2 從最近一次真實經歷開始問”">​</a></h3><p>可以先從這類問題開始：</p><ul><li>最近一次遇到這個問題是什麼時候？</li><li>當時發生了什麼？</li><li>你第一反應是怎麼處理的？</li></ul><p>一旦對話進入具體事件，資訊質量通常會明顯提升。</p><h3 id="_6-3-往下追問行為、成本和替代方案" tabindex="-1">6.3 往下追問行為、成本和替代方案 <a class="header-anchor" href="#_6-3-往下追問行為、成本和替代方案" aria-label="Permalink to “6.3 往下追問行為、成本和替代方案”">​</a></h3><p>繼續問：</p><ul><li>你現在用什麼辦法解決？</li><li>這個辦法最不舒服的地方是什麼？</li><li>你為此花過多少時間、錢或者精力？</li><li>你試過別的方法嗎？為什麼沒繼續用？</li></ul><h3 id="_6-4-最後再判斷痛感和優先順序" tabindex="-1">6.4 最後再判斷痛感和優先順序 <a class="header-anchor" href="#_6-4-最後再判斷痛感和優先順序" aria-label="Permalink to “6.4 最後再判斷痛感和優先順序”">​</a></h3><p>你不需要直接問“痛不痛”，可以從細節裡判斷：</p><ul><li>他是不是經常遇到</li><li>他是不是已經在主動補救</li><li>他是不是已經願意為此付出成本</li><li>他在講這件事時是不是帶著明顯情緒</li></ul><p>這些都比一句“這是不是你的痛點”更有用。</p><h2 id="_7-一個更完整的例子" tabindex="-1">7. 一個更完整的例子 <a class="header-anchor" href="#_7-一個更完整的例子" aria-label="Permalink to “7. 一個更完整的例子”">​</a></h2><p>假設你想做一個“AI 幫大學生改簡歷”的產品。</p><h3 id="錯誤問法" tabindex="-1">錯誤問法 <a class="header-anchor" href="#錯誤問法" aria-label="Permalink to “錯誤問法”">​</a></h3><p>你去問同學：</p><blockquote><p>我想做一個 AI 簡歷最佳化工具，你覺得怎麼樣？<br> 如果它能根據崗位自動改簡歷，你會不會用？</p></blockquote><p>這時候，對方很可能會說：</p><ul><li>聽起來挺好</li><li>我覺得應該有用</li><li>如果免費我會試試</li></ul><p>這些回答幾乎沒有辦法幫你判斷需求到底強不強。</p><h3 id="更好的問法" tabindex="-1">更好的問法 <a class="header-anchor" href="#更好的問法" aria-label="Permalink to “更好的問法”">​</a></h3><p>你可以改成：</p><blockquote><p>你最近一次改簡歷是什麼時候？<br> 當時為什麼要改？<br> 你是怎麼改的？<br> 哪一步最卡？<br> 你有沒有找過別人幫你看？<br> 你以前為簡歷這件事花過錢或者花過很多時間嗎？</p></blockquote><p>透過這些問題，你可能得到的資訊會是：</p><ul><li>很多人不是不會寫，而是不知道怎麼針對不同崗位改寫</li><li>他們最痛的不是排版，而是“不知道哪些經歷值得寫”</li><li>他們會拖延，不是因為懶，而是因為每次改簡歷都很消耗</li><li>他們已經在用學長建議、模板網站、AI 工具和朋友幫看來勉強解決</li></ul><p>這時候，你離真實問題就近得多了。</p><h2 id="_8-the-mom-test-和-jtbd-怎麼配合用" tabindex="-1">8. The Mom Test 和 JTBD 怎麼配合用 <a class="header-anchor" href="#_8-the-mom-test-和-jtbd-怎麼配合用" aria-label="Permalink to “8. The Mom Test 和 JTBD 怎麼配合用”">​</a></h2><p>如果說 JTBD 幫你看清“使用者想完成什麼進展”，那麼 The Mom Test 更像是在教你：</p><p><strong>怎麼透過訪談，確認這個 job 是不是真的存在。</strong></p><p>你完全可以把兩者接起來使用：</p><ol><li>先用 JTBD 假設一個 job</li><li>再用 The Mom Test 的方式，去問使用者最近一次真實經歷</li><li>看看這個 job 是否真的高頻、真實、值得優先做</li></ol><p>比如你的 JTBD 假設是：</p><blockquote><p>當我準備投遞實習時，我想快速把舊簡歷改成貼合崗位的版本，以便儘快完成投遞。</p></blockquote><p>那你就可以用 The Mom Test 風格的問題去驗證：</p><ul><li>你最近一次投遞是什麼時候？</li><li>當時你是怎麼改簡歷的？</li><li>哪一段最難寫？</li><li>你改完之後怎麼判斷它夠不夠好？</li></ul><p>這樣，方法就連起來了：</p><ul><li>JTBD 幫你定義需求假設</li><li>The Mom Test 幫你訪談驗證假設</li></ul><h2 id="_9-新手做使用者訪談時最常見的誤區" tabindex="-1">9. 新手做使用者訪談時最常見的誤區 <a class="header-anchor" href="#_9-新手做使用者訪談時最常見的誤區" aria-label="Permalink to “9. 新手做使用者訪談時最常見的誤區”">​</a></h2><h3 id="_9-1-把訪談做成產品介紹會" tabindex="-1">9.1 把訪談做成產品介紹會 <a class="header-anchor" href="#_9-1-把訪談做成產品介紹會" aria-label="Permalink to “9.1 把訪談做成產品介紹會”">​</a></h3><p>你一講太多自己的想法，對方就容易開始配合你，而不是告訴你真實情況。</p><h3 id="_9-2-訪談物件全是熟人" tabindex="-1">9.2 訪談物件全是熟人 <a class="header-anchor" href="#_9-2-訪談物件全是熟人" aria-label="Permalink to “9.2 訪談物件全是熟人”">​</a></h3><p>熟人不是不能聊，但熟人更容易鼓勵你。你至少需要混合一些更接近真實使用者的人，而不是隻找支援你的人。</p><h3 id="_9-3-過早追著問功能" tabindex="-1">9.3 過早追著問功能 <a class="header-anchor" href="#_9-3-過早追著問功能" aria-label="Permalink to “9.3 過早追著問功能”">​</a></h3><p>如果你還沒搞清楚問題，就開始追問按鈕、介面、功能細節，通常是在太早進入解決方案。</p><h3 id="_9-4-把一句-我會用-當成驗證結果" tabindex="-1">9.4 把一句“我會用”當成驗證結果 <a class="header-anchor" href="#_9-4-把一句-我會用-當成驗證結果" aria-label="Permalink to “9.4 把一句“我會用”當成驗證結果”">​</a></h3><p>訪談最多幫你判斷方向，不等於已經完成驗證。真正的驗證，最終還是要看使用者是否願意付出真實成本，比如時間、切換成本、試用行為，甚至付費。</p><h3 id="_9-5-訪談結束後不整理" tabindex="-1">9.5 訪談結束後不整理 <a class="header-anchor" href="#_9-5-訪談結束後不整理" aria-label="Permalink to “9.5 訪談結束後不整理”">​</a></h3><p>如果你聊完就放著，資訊很快會變成模糊印象。最好儘快整理：</p><ul><li>出現頻率高的問題</li><li>使用者原話裡的情緒詞</li><li>當前替代方案</li><li>已經付出的成本</li><li>你自己的新判斷</li></ul><h2 id="_10-可以直接複製去用的問題清單" tabindex="-1">10. 可以直接複製去用的問題清單 <a class="header-anchor" href="#_10-可以直接複製去用的問題清單" aria-label="Permalink to “10. 可以直接複製去用的問題清單”">​</a></h2><p>如果你想盡快開始，這裡有一組足夠通用的問題。</p><h3 id="開場問題" tabindex="-1">開場問題 <a class="header-anchor" href="#開場問題" aria-label="Permalink to “開場問題”">​</a></h3><ul><li>最近一次你遇到這個問題是什麼時候？</li><li>當時具體發生了什麼？</li></ul><h3 id="行為問題" tabindex="-1">行為問題 <a class="header-anchor" href="#行為問題" aria-label="Permalink to “行為問題”">​</a></h3><ul><li>你當時是怎麼處理的？</li><li>你為什麼會選擇這種方式？</li></ul><h3 id="成本問題" tabindex="-1">成本問題 <a class="header-anchor" href="#成本問題" aria-label="Permalink to “成本問題”">​</a></h3><ul><li>這件事一般會花掉你多少時間或精力？</li><li>你有沒有為瞭解決它花過錢？</li></ul><h3 id="替代方案問題" tabindex="-1">替代方案問題 <a class="header-anchor" href="#替代方案問題" aria-label="Permalink to “替代方案問題”">​</a></h3><ul><li>你試過別的工具或辦法嗎？</li><li>為什麼最後沒有繼續用？</li></ul><h3 id="收尾問題" tabindex="-1">收尾問題 <a class="header-anchor" href="#收尾問題" aria-label="Permalink to “收尾問題”">​</a></h3><ul><li>如果以後還遇到同樣的問題，你覺得最理想的解決方式應該是什麼樣？</li></ul><p>注意，這個收尾問題可以問，但最好放在後面。因為前面你更需要拿到事實，而不是願望。</p><h2 id="_11-小結" tabindex="-1">11. 小結 <a class="header-anchor" href="#_11-小結" aria-label="Permalink to “11. 小結”">​</a></h2><p>The Mom Test 最重要的貢獻，不是給你一套“更會聊天”的技巧，而是幫你建立一種更清醒的判斷方式：</p><ul><li>不要太快相信別人對你點子的誇獎</li><li>不要把“如果有我會用”當成真實需求</li><li>不要讓訪談變成你在尋找認可</li></ul><p>真正有價值的訪談，應該儘量回到這些東西上：</p><ul><li>使用者最近一次真實經歷</li><li>他現在怎麼處理</li><li>他已經付出了什麼成本</li><li>他在哪些地方明顯不舒服</li></ul><p>當你開始這樣問，你得到的資訊雖然有時沒那麼好聽，但通常更有用。<br> 而做產品時，<strong>有用的真相，永遠比好聽的鼓勵更重要。</strong></p><p><a id="mom-ai"></a></p><h2 id="_12-如何利用-ai-幫你做使用者訪談" tabindex="-1"><a href="#top-mom">12. 如何利用 AI 幫你做使用者訪談</a> <a class="header-anchor" href="#_12-如何利用-ai-幫你做使用者訪談" aria-label="Permalink to “12. 如何利用 AI 幫你做使用者訪談”">​</a></h2><p>The Mom Test 本質上還是一套“和真人聊”的方法，所以 AI 不能替代真實訪談。但 AI 非常適合在訪談前、中、後給你打輔助，尤其適合幫新手降低門檻。</p><h3 id="_12-1-讓-ai-幫你把-容易問廢-的問題改寫掉" tabindex="-1">12.1 讓 AI 幫你把“容易問廢”的問題改寫掉 <a class="header-anchor" href="#_12-1-讓-ai-幫你把-容易問廢-的問題改寫掉" aria-label="Permalink to “12.1 讓 AI 幫你把“容易問廢”的問題改寫掉”">​</a></h3><p>很多人知道自己不該問“你覺得我這個想法怎麼樣”，但一開口還是會回到這種句子。你可以先把自己準備問的問題交給 AI，讓它幫你改寫：</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>下面是我準備做使用者訪談時想問的問題：</span></span>
<span class="line"><span>[貼上你的問題]</span></span>
<span class="line"><span></span></span>
<span class="line"><span>請你用 The Mom Test 的原則幫我改寫：</span></span>
<span class="line"><span>1. 刪掉意見型問題</span></span>
<span class="line"><span>2. 刪掉假設未來的問題</span></span>
<span class="line"><span>3. 儘量改成圍繞過去真實行為、已有替代方案和已付成本的提問</span></span>
<span class="line"><span>4. 最後整理成一套 8-10 個可以直接訪談的問題清單</span></span></code></pre></div><p>一個很小白的輸入也完全可以：</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>我想問使用者：</span></span>
<span class="line"><span>1. 你覺得我做一個 AI 改簡歷工具怎麼樣？</span></span>
<span class="line"><span>2. 你會不會用？</span></span>
<span class="line"><span>3. 你願不願意付費？</span></span>
<span class="line"><span></span></span>
<span class="line"><span>請幫我改成更好的問法。</span></span></code></pre></div><p>AI 可能給出的有用輸出會像這樣：</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>改寫後的問題：</span></span>
<span class="line"><span></span></span>
<span class="line"><span>1. 你最近一次改簡歷是什麼時候？</span></span>
<span class="line"><span>2. 當時為什麼要改？</span></span>
<span class="line"><span>3. 你是怎麼改的？</span></span>
<span class="line"><span>4. 哪一步最花時間？</span></span>
<span class="line"><span>5. 你有沒有找別人幫你看？</span></span>
<span class="line"><span>6. 你以前有沒有為簡歷修改花過錢或花過很多時間？</span></span></code></pre></div><p>這種輸出很有幫助，因為它直接把你原本“在問意見”的問題，改成了“在問真實行為”的問題。</p><h3 id="_12-2-讓-ai-幫你生成不同物件的訪談提綱" tabindex="-1">12.2 讓 AI 幫你生成不同物件的訪談提綱 <a class="header-anchor" href="#_12-2-讓-ai-幫你生成不同物件的訪談提綱" aria-label="Permalink to “12.2 讓 AI 幫你生成不同物件的訪談提綱”">​</a></h3><p>同一個方向，面對不同人羣，訪談重點會不一樣。比如學生、HR、自由職業者，關心點完全不同。你可以讓 AI 幫你針對不同物件各出一版提綱：</p><ul><li>面向新手使用者，重點瞭解最近一次真實經歷</li><li>面向重度使用者，重點瞭解替代方案和痛感</li><li>面向付費使用者，重點瞭解是否已經為此付過成本</li></ul><p>這樣你在真正聊天時會更有節奏，而不會每個人都問同一套問題。</p><p>比如你可以直接這樣輸入：</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>我要聊兩類人：</span></span>
<span class="line"><span>1. 第一次找實習的大學生</span></span>
<span class="line"><span>2. 已經幫別人看過很多簡歷的學長學姐</span></span>
<span class="line"><span></span></span>
<span class="line"><span>請分別給我一套訪談提綱，每套 6 個問題。</span></span></code></pre></div><p>AI 可能輸出：</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>對大學生：</span></span>
<span class="line"><span>1. 最近一次投實習是什麼時候？</span></span>
<span class="line"><span>2. 當時最卡的是哪一步？</span></span>
<span class="line"><span>3. 你怎麼知道自己的簡歷能不能投？</span></span>
<span class="line"><span>...</span></span>
<span class="line"><span></span></span>
<span class="line"><span>對學長學姐：</span></span>
<span class="line"><span>1. 你最近一次幫別人看簡歷是什麼時候？</span></span>
<span class="line"><span>2. 你最常看到哪些明顯問題？</span></span>
<span class="line"><span>3. 學弟學妹最容易卡在哪一步？</span></span>
<span class="line"><span>...</span></span></code></pre></div><p>這樣一來，你不用自己從零編問題，訪談準備會輕鬆很多。</p><h3 id="_12-3-讓-ai-幫你整理訪談記錄" tabindex="-1">12.3 讓 AI 幫你整理訪談記錄 <a class="header-anchor" href="#_12-3-讓-ai-幫你整理訪談記錄" aria-label="Permalink to “12.3 讓 AI 幫你整理訪談記錄”">​</a></h3><p>訪談做完之後，最容易出現的問題不是“沒資訊”，而是“資訊太散”。AI 很適合幫你把碎片化對話整理成結構化筆記：</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>下面是我和 3 位使用者的訪談記錄。</span></span>
<span class="line"><span>請按 The Mom Test 的角度整理：</span></span>
<span class="line"><span>1. 哪些內容是事實，哪些只是意見</span></span>
<span class="line"><span>2. 使用者最近一次真實行為是什麼</span></span>
<span class="line"><span>3. 當前替代方案是什麼</span></span>
<span class="line"><span>4. 使用者已經付出的時間、金錢或精力成本是什麼</span></span>
<span class="line"><span>5. 哪些問題被反覆提到</span></span>
<span class="line"><span>6. 哪些說法聽起來積極，但證據不足</span></span></code></pre></div><p>這一步尤其有價值，因為它能幫你把“聽起來不錯”的內容和“真的能支撐判斷”的內容分開。</p><p>一個簡單輸入可以是：</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>這是我和一個使用者聊完後的記錄：</span></span>
<span class="line"><span></span></span>
<span class="line"><span>- 她說如果有個工具應該會試試</span></span>
<span class="line"><span>- 她上週為了改簡歷花了一個晚上</span></span>
<span class="line"><span>- 她現在主要靠朋友幫看</span></span>
<span class="line"><span>- 她說最難的是不知道改到什麼程度算可以投</span></span>
<span class="line"><span></span></span>
<span class="line"><span>請你幫我分一下，哪些是意見，哪些是事實。</span></span></code></pre></div><p>AI 可能輸出：</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>意見：</span></span>
<span class="line"><span>- 如果有個工具應該會試試</span></span>
<span class="line"><span></span></span>
<span class="line"><span>事實：</span></span>
<span class="line"><span>- 上週為了改簡歷花了一個晚上</span></span>
<span class="line"><span>- 當前替代方案是找朋友幫看</span></span>
<span class="line"><span>- 最難點是不知道什麼時候算“可以投”</span></span>
<span class="line"><span></span></span>
<span class="line"><span>可用於判斷需求的重點：</span></span>
<span class="line"><span>- 這個問題最近剛發生過</span></span>
<span class="line"><span>- 使用者已經投入了明顯時間成本</span></span>
<span class="line"><span>- 當前方案依賴他人，不穩定</span></span></code></pre></div><p>這個輸出就能很直觀地告訴新手：哪些話能拿來做判斷，哪些話只能聽聽。</p><h3 id="_12-4-讓-ai-先做一輪輕量級網路搜尋" tabindex="-1">12.4 讓 AI 先做一輪輕量級網路搜尋 <a class="header-anchor" href="#_12-4-讓-ai-先做一輪輕量級網路搜尋" aria-label="Permalink to “12.4 讓 AI 先做一輪輕量級網路搜尋”">​</a></h3><p>如果你還沒開始訪談，可以先讓 AI 幫你做一些很輕的外部調研，比如：</p><ul><li>公開社羣裡，大家最近是怎麼抱怨這個問題的</li><li>現有工具被吐槽最多的是什麼</li><li>使用者是不是已經為相似問題花過錢</li><li>市場上有哪些替代方案已經存在</li></ul><p>這類資訊不能替代真人訪談，但能幫你更快進入狀態，知道該從哪裡切入問題。</p><p>比如一個簡單輸入可以是：</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>請你幫我搜一下：</span></span>
<span class="line"><span>“大學生改簡歷時最常吐槽什麼”</span></span>
<span class="line"><span>幫我整理出 5 條最常見抱怨，用很白話的話寫出來。</span></span></code></pre></div><p>AI 可能輸出：</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>常見抱怨：</span></span>
<span class="line"><span></span></span>
<span class="line"><span>1. 不知道簡歷上到底該寫什麼</span></span>
<span class="line"><span>2. 每投一個崗位都要改，太累</span></span>
<span class="line"><span>3. 改了很多版還是不確定好不好</span></span>
<span class="line"><span>4. 沒人能給靠譜反饋</span></span>
<span class="line"><span>5. 總覺得還沒準備好，所以一直拖</span></span></code></pre></div><p>這種結果的價值在於，它會讓你更容易找到訪談切入口。</p><h3 id="_12-5-讓-ai-扮演-訪談覆盤教練" tabindex="-1">12.5 讓 AI 扮演“訪談覆盤教練” <a class="header-anchor" href="#_12-5-讓-ai-扮演-訪談覆盤教練" aria-label="Permalink to “12.5 讓 AI 扮演“訪談覆盤教練””">​</a></h3><p>你還可以把自己剛做完的一場訪談記錄丟給 AI，讓它幫你挑刺：</p><div class="language-text"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>下面是我的一段使用者訪談記錄。</span></span>
<span class="line"><span>請從 The Mom Test 的角度幫我覆盤：</span></span>
<span class="line"><span>1. 我哪些問題問得太像在找認可</span></span>
<span class="line"><span>2. 哪些問題帶有明顯引導</span></span>
<span class="line"><span>3. 哪些地方本來可以繼續追問事實</span></span>
<span class="line"><span>4. 如果再來一次，這段對話可以怎麼問得更好</span></span></code></pre></div><p>這對新手特別有幫助，因為你會更快建立一種“我到底是在收集證據，還是在收集鼓勵”的敏感度。</p><h2 id="📚-assignments" tabindex="-1">📚 Assignments <a class="header-anchor" href="#📚-assignments" aria-label="Permalink to “📚 Assignments”">​</a></h2><p>請你根據上文內容，完成下列作業：</p><ol><li>選一個你最近想做的產品方向，先寫出 5 個你原本會問的“容易問廢”的問題</li><li>把這 5 個問題改寫成更符合 The Mom Test 風格的提問</li><li>找 3 個潛在使用者，至少問出一次“最近一次你遇到這個問題是什麼時候”</li><li>訪談結束後整理 4 類資訊：真實行為、替代方案、已付成本、反覆出現的困難</li></ol><h2 id="延伸閱讀" tabindex="-1">延伸閱讀 <a class="header-anchor" href="#延伸閱讀" aria-label="Permalink to “延伸閱讀”">​</a></h2><ul><li><a href="https://momtestbook.com/" target="_blank" rel="noreferrer">The Mom Test 官方網站</a></li><li><a href="https://www.robfitz.com/the-mom-test/" target="_blank" rel="noreferrer">Rob Fitzpatrick: The Mom Test</a></li></ul>`,185))])}}});export{u as __pageData,m as default};
